const getOrdinalSuffix = (day: number) => {
    if (day > 3 && day < 21) return 'th';
    switch (day % 10) {
      case 1:  return "st";
      case 2:  return "nd";
      case 3:  return "rd";
      default: return "th";
    }
};



const getNextReminderDate = (day: number) => {
    const today = new Date();
    let nextDate = new Date(today.getFullYear(), today.getMonth(), day);
    
    // If the date for this month has passed, move to next month
    if (nextDate < today) {
        nextDate = new Date(today.getFullYear(), today.getMonth() + 1, day);
    }
    return nextDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
};

const formatFundingTier = (amount?: number | null) => {
  if (typeof amount !== 'number' || Number.isNaN(amount)) {
    return 'N/A';
  }

  if (amount <= 50_000) {
    return 'Starter File (0 to 50K)';
  }

  if (amount <= 100_000) {
    return 'Mid-tier File (51K to 100K)';
  }

  return 'Upper-tier File (101K+)';
};

