const lawTagsFromLawset = (lawset: Record<string, string[]>) =>
  Object.entries(lawset).flatMap(([cat, items]) => items.map((law) => `${cat} ${law}`));

const supportTemplateBureauCode: Record<string, string> = {
  experian: "EX",
  equifax: "EQ",
  transunion: "TU",
};

const mapReportBureauName = mapCreditReportBureauName;

const getNegativeItemAccountKey = (value: any, fallback: any = ''): string => {
  const digitsOnly = String(value ?? '').replace(/\D/g, '');
  if (digitsOnly) {
    return digitsOnly.length >= 4 ? digitsOnly.slice(-4) : digitsOnly;
  }
  return String(fallback ?? value ?? '').toLowerCase();
};

const normalizeNegativeItemBureaus = (value: any): string[] => {
  const allBureaus = ['Experian', 'TransUnion', 'Equifax'];
  if (!value && value !== 0) return [];
  if (Array.isArray(value)) {
    return Array.from(new Set(value.map((entry) => mapReportBureauName(entry)).filter(Boolean)));
  }

  const text = String(value).trim();
  if (!text) return [];
  const lowered = text.toLowerCase();

  if (lowered === 'multiple') return allBureaus;
  if (text.includes(',')) {
    return Array.from(new Set(text.split(',').map((entry) => mapReportBureauName(entry.trim())).filter(Boolean)));
  }
  if (text.includes('|')) {
    return Array.from(new Set(text.split('|').map((entry) => mapReportBureauName(entry.trim())).filter(Boolean)));
  }

  return [mapReportBureauName(text)];
};

const negativeItemMatchesBureauFilter = (item: any, bureauFilter: string): boolean => {
  const normalizedFilter = String(bureauFilter || '').trim().toLowerCase();
  if (!normalizedFilter) return false;
  return normalizeNegativeItemBureaus(item?.bureau).some((bureau) => bureau.toLowerCase().includes(normalizedFilter));
};

const getLatePaymentNegativeLabel = (account: any): string => {
  const status = String(account?.status || account?.AccountStatus || account?.AccountCondition || '').trim();
  const paymentStatus = String(account?.paymentHistory || account?.PaymentStatus || '').trim();
  const worstPayStatus = String(account?.WorstPayStatus || account?.worstStatus || '').trim();
  const combined = `${paymentStatus} ${worstPayStatus} ${status}`.toLowerCase();

  if (/\b180\b/.test(combined)) return '180 Days Late';
  if (/\b150\b/.test(combined)) return '150 Days Late';
  if (/\b120\b/.test(combined)) return '120 Days Late';
  if (/\b90\b/.test(combined)) return '90 Days Late';
  if (/\b60\b/.test(combined)) return '60 Days Late';
  if (/\b30\b/.test(combined)) return '30 Days Late';
  if (combined.includes('past due')) return 'Past Due';
  if (combined.includes('delinquent')) return 'Delinquent';
  if (combined.includes('default')) return 'Default';
  if (combined.includes('late')) return 'Late Payment';

  const payStatusHistory = String(account?.PayStatusHistory || account?.payStatusHistory || '').toUpperCase();
  const maxSeverityDigit = [...payStatusHistory].reduce((max, char) => {
    const digit = Number.parseInt(char, 10);
    return Number.isNaN(digit) ? max : Math.max(max, digit);
  }, 0);

  if (maxSeverityDigit >= 6) return '180 Days Late';
  if (maxSeverityDigit === 5) return '150 Days Late';
  if (maxSeverityDigit === 4) return '120 Days Late';
  if (maxSeverityDigit === 3) return '90 Days Late';
  if (maxSeverityDigit === 2) return '60 Days Late';
  if (maxSeverityDigit === 1) return '30 Days Late';

  return paymentStatus || worstPayStatus || 'Late Payment';
};

const normalizeNegativeItemCategoryKey = (value: any): string => {
  const text = String(value || '').trim().toLowerCase();
  if (!text) return '';
  if (text.includes('personal info') || text.includes('personal-information') || text.includes('personal information') || text.includes('identity')) return 'personal-information';
  if (text.includes('student')) return 'student-loan';
  if (text.includes('soft') && text.includes('inquir')) return 'soft-inquiry';
  if (text.includes('hard') && text.includes('inquir')) return 'hard-inquiry';
  if (text.includes('inquir')) return 'hard-inquiry';
  if (text.includes('public')) return 'public-record';
  if (text.includes('charge')) return 'charge-off';
  if (text.includes('collect')) return 'collection';
  if (text.includes('account') || text.includes('late') || text.includes('delinqu')) return 'late-payment';
  return text;
};

const getGeneratedLetterCategorySortRank = (value: any): number => {
  switch (normalizeNegativeItemCategoryKey(value)) {
    case 'personal-information': return 0;
    case 'public-record': return 1;
    case 'hard-inquiry':
    case 'soft-inquiry':
      return 2;
    case 'charge-off':
    case 'collection':
      return 3;
    case 'late-payment':
      return 4;
    case 'student-loan':
      return 5;
    default:
      return 6;
  }
};

const sortGeneratedLetterOutputs = (outputs: GeneratedLetter[]) => {
  return outputs
    .map((output, index) => ({ output, index }))
    .sort((left, right) => {
      const rankDiff = getGeneratedLetterCategorySortRank(left.output.categoryKey || left.output.categoryLabel)
        - getGeneratedLetterCategorySortRank(right.output.categoryKey || right.output.categoryLabel);
      if (rankDiff !== 0) return rankDiff;
      return left.index - right.index;
    })
    .map(({ output }) => output);
};

const buildNegativeItemsFromReport = (base: any): any[] => {
  const root = base?.reportData || base;
  const nestedReport = root?.reportData || root?.report_data || null;
  const accounts = Array.isArray(root?.accounts)
    ? root.accounts
    : Array.isArray(root?.Accounts)
    ? root.Accounts
    : Array.isArray(nestedReport?.Accounts)
    ? nestedReport.Accounts
    : [];
  const collections = Array.isArray(root?.collections)
    ? root.collections
    : Array.isArray(root?.Collections)
    ? root.Collections
    : Array.isArray(nestedReport?.Collections)
    ? nestedReport.Collections
    : [];
  const inquiries = Array.isArray(root?.inquiries)
    ? root.inquiries
    : Array.isArray(root?.Inquiries)
    ? root.Inquiries
    : Array.isArray(nestedReport?.Inquiries)
    ? nestedReport.Inquiries
    : [];
  const publicRecords = Array.isArray(root?.publicRecords)
    ? root.publicRecords
    : Array.isArray(root?.PublicRecords)
    ? root.PublicRecords
    : Array.isArray(nestedReport?.PublicRecords)
    ? nestedReport.PublicRecords
    : [];

  const items: any[] = [];
  const seen = new Set<string>();
  const addItem = (item: any) => {
    const rawBureau = item?.bureau;
    const bureaus = normalizeNegativeItemBureaus(rawBureau);
    // If item spans multiple bureaus, create a separate entry per bureau so each can be selected independently
    const bureauList = bureaus.length > 1 ? bureaus : [mapReportBureauName(rawBureau)];
    for (const bureau of bureauList) {
      const key = `${String(item?.category || '').toLowerCase()}|${String(item?.type || '').toLowerCase()}|${String(item?.accountKey || '').toLowerCase()}|${String(item?.creditor || '').toLowerCase()}|${bureau.toLowerCase()}`;
      if (seen.has(key)) continue;
      seen.add(key);
      items.push({
        ...item,
        bureau,
        key,
      });
    }
  };

  const latePaymentAccounts = Array.isArray(accounts)
    ? accounts.filter((account: any) => isLatePaymentNegativeAccount(account))
    : [];

  latePaymentAccounts.forEach((account: any, index: number) => {
    const accountIdentifier = account.accountNumber || account.AccountNumber || account.id || `${account.creditor || account.CreditorName || 'late-payment'}-${index}`;
    const accountKey = getNegativeItemAccountKey(accountIdentifier, `${account.creditor || account.CreditorName || 'late-payment'}-${index}`);
    const lateType = getLatePaymentNegativeLabel(account);

    addItem({
      id: accountIdentifier,
      type: lateType,
      creditor: account.creditor || account.CreditorName || 'Unknown',
      bureau: account.bureau || account.BureauId,
      accountNumber: account.accountNumber || account.AccountNumber || account.id,
      accountDate: account.DateOpened || account.dateOpened || account.opened || account.DateReported || account.dateReported || account.reported,
      category: 'late-payment',
      accountKey,
      status: lateType,
      dateOpened: account.DateOpened || account.dateOpened || account.opened || '',
      dateOfFirstDelinquency: account.PayStatusHistoryStartDate || account.DateOfFirstDelinquency || '',
      accountStatus: account.AccountStatus || account.accountStatus || account.status || '',
      accountStatusDate: account.DateAccountStatus || account.accountStatusDate || '',
      currentBalance: account.CurrentBalance || account.currentBalance || account.balance || account.Balance || '',
      originalLoanAmount: account.HighBalance || account.highBalance || account.OriginalLoanAmount || '',
      dateOfLastPayment: account.DateReported || account.DateOfLastPayment || '',
      dateOfLastActivity: account.DateOfLastActivity || account.dateOfLastActivity || '',
      accountType: account.AccountType || account.accountType || account.type || '',
      accountResponsibility: account.AccountDesignator || account.AccountResponsibility || '',
      accountTerms: account.TermType || account.AccountTerms || '',
      scheduledPaymentAmount: account.AmountPastDue || account.ScheduledPaymentAmount || '',
      dateClosed: account.DateClosed || '',
      highBalance: account.HighBalance || account.highBalance || '',
      paymentStatus: account.PaymentStatus || account.paymentStatus || '',
    });
  });

  const chargeOffAccounts = Array.isArray(accounts)
    ? accounts.filter((account: any) => isChargeOffNegativeAccount(account) && !latePaymentAccounts.includes(account))
    : [];

  chargeOffAccounts.forEach((account: any, index: number) => {
    const accountIdentifier = account.accountNumber || account.AccountNumber || account.id || `${account.creditor || account.CreditorName || 'charge-off'}-${index}`;
    const accountKey = getNegativeItemAccountKey(accountIdentifier, `${account.creditor || account.CreditorName || 'charge-off'}-${index}`);

    addItem({
      id: accountIdentifier,
      type: 'Charge Off',
      creditor: account.creditor || account.CreditorName || 'Unknown',
      bureau: account.bureau || account.BureauId,
      accountNumber: account.accountNumber || account.AccountNumber || account.id,
      accountDate: account.DateOpened || account.dateOpened || account.opened || account.DateReported || account.dateReported || account.reported,
      category: 'charge-off',
      accountKey,
      status: account.PaymentStatus || account.status || account.AccountStatus || 'Charge Off',
      dateOpened: account.DateOpened || account.dateOpened || account.opened || '',
      dateOfFirstDelinquency: account.PayStatusHistoryStartDate || account.DateOfFirstDelinquency || '',
      accountStatus: account.AccountStatus || account.accountStatus || account.status || '',
      accountStatusDate: account.DateAccountStatus || account.accountStatusDate || '',
      currentBalance: account.CurrentBalance || account.currentBalance || account.balance || account.Balance || '',
      originalLoanAmount: account.HighBalance || account.highBalance || account.OriginalLoanAmount || '',
      dateOfLastPayment: account.DateReported || account.DateOfLastPayment || '',
      dateOfLastActivity: account.DateOfLastActivity || account.dateOfLastActivity || '',
      accountType: account.AccountType || account.accountType || account.type || '',
      accountResponsibility: account.AccountDesignator || account.AccountResponsibility || '',
      accountTerms: account.TermType || account.AccountTerms || '',
      scheduledPaymentAmount: account.AmountPastDue || account.ScheduledPaymentAmount || '',
      dateClosed: account.DateClosed || '',
      highBalance: account.HighBalance || account.highBalance || '',
      paymentStatus: account.PaymentStatus || account.paymentStatus || '',
    });
  });

  if (Array.isArray(collections)) {
    const latePaymentIds = new Set(latePaymentAccounts.map((account: any) => String(account.accountNumber || account.AccountNumber || account.id || '')));
    collections.forEach((collection: any, index: number) => {
      const collectionIdentifier = collection.accountNumber || collection.AccountNumber || collection.id || `${collection.agency || collection.originalCreditor || 'collection'}-${index}`;
      if (latePaymentIds.has(String(collectionIdentifier))) return;
      const accountKey = getNegativeItemAccountKey(collectionIdentifier, `${collection.agency || collection.originalCreditor || 'collection'}-${index}`);

      addItem({
        id: collection.id || collectionIdentifier,
        type: 'Collection',
        creditor: collection.agency || collection.originalCreditor || collection.creditor || collection.CreditorName || 'Collection Agency',
        bureau: collection.bureau || collection.BureauId || 'Multiple',
        accountNumber: collection.accountNumber || collection.AccountNumber || collection.id,
        accountDate: collection.dateOpened || collection.DateOpened || collection.dateReported || collection.DateReported || collection.lastActivity,
        category: 'collection',
        accountKey,
        status: collection.status || collection.AccountStatus || collection.PaymentStatus || 'Collection',
        dateOpened: collection.dateOpened || collection.DateOpened || '',
        dateOfFirstDelinquency: collection.PayStatusHistoryStartDate || collection.dateOfFirstDelinquency || '',
        accountStatus: collection.status || collection.AccountStatus || 'Collection',
        accountStatusDate: collection.DateAccountStatus || '',
        currentBalance: collection.balance || collection.CurrentBalance || collection.currentBalance || '',
        originalLoanAmount: collection.HighBalance || collection.highBalance || collection.originalAmount || '',
        dateOfLastPayment: collection.DateReported || collection.dateOfLastPayment || '',
        dateOfLastActivity: collection.lastActivity || collection.DateOfLastActivity || '',
        accountType: collection.AccountType || 'Collection',
        accountResponsibility: collection.AccountDesignator || collection.responsibility || '',
        accountTerms: collection.TermType || collection.terms || '',
        scheduledPaymentAmount: collection.AmountPastDue || collection.monthlyPayment || '',
        dateClosed: collection.dateClosed || '',
        highBalance: collection.highBalance || collection.HighBalance || '',
        paymentStatus: collection.PaymentStatus || collection.paymentStatus || '',
      });
    });
  }

  if (Array.isArray(publicRecords)) {
    publicRecords.forEach((record: any, index: number) => {
      const recordType = record.type || record.Type || record.RecordType || 'public-record';
      const recordIdentifier = record.caseNumber || record.CaseNumber || record.id || `${recordType}-${index}`;
      const accountKey = getNegativeItemAccountKey(recordIdentifier, `${recordType}-${index}`);

      addItem({
        id: record.id || recordIdentifier,
        type: record.type || record.Type || record.RecordType || 'Public Record',
        creditor: record.creditor || record.Court || 'Court/Government',
        bureau: record.bureau || record.BureauId || 'Multiple',
        accountNumber: record.caseNumber || record.CaseNumber || record.id,
        accountDate: record.Date || record.date || record.DateFiled || record.filingDate || record.ClosingDate || record.dischargeDate,
        category: 'public-record',
        accountKey,
        status: record.status || record.Status || record.Classification || record.type || record.Type || record.RecordType || 'Public Record',
        classification: record.Classification || record.classification || '',
        amount: record.Amount ?? record.amount ?? '',
        dateFiled: record.DateFiled || record.filingDate || '',
        dateReported: record.DateReported || record.dateReported || '',
        industry: record.Industry || record.industry || '',
        accountDesignator: record.AccountDesignator || record.accountDesignator || '',
        referenceNumber: record.ReferenceNumber || record.referenceNumber || '',
        closingDate: record.ClosingDate || record.closingDate || record.dischargeDate || '',
        court: record.Court || record.court || '',
        assetAmount: record.AssetAmount ?? record.assetAmount ?? '',
        liability: record.Liability ?? record.liability ?? '',
        exemptAmount: record.ExemptAmount ?? record.exemptAmount ?? '',
        remarks: record.Remarks || record.Remark || record.remarks || '',
        name: record.Name || record.name || '',
        caseNumber: record.CaseNumber || record.caseNumber || record.id || '',
      });
    });
  }

  if (Array.isArray(inquiries)) {
    inquiries.forEach((inquiry: any, index: number) => {
      const inquiryType = String(inquiry.type || '').toLowerCase();
      const inquiryCode = String(inquiry.InquiryType || '').toLowerCase();
      const creditor = inquiry.company || inquiry.creditorName || inquiry.CreditorName || 'Inquiry';
      const inquiryDate = inquiry.date || inquiry.DateInquiry || '';
      const category = inquiryType === 'hard' || inquiryCode === 'i' ? 'hard-inquiry' : 'soft-inquiry';
      const inquiryIdentifier = inquiry.id || `INQ-${category}-${creditor}-${inquiryDate || index}`;
      const accountKey = getNegativeItemAccountKey(`INQ|${category}|${creditor}|${inquiryDate || index}`, inquiryIdentifier);

      addItem({
        id: inquiry.id || inquiryIdentifier,
        type: 'Inquiry',
        creditor,
        bureau: inquiry.bureau || inquiry.BureauId,
        accountNumber: inquiry.id || `INQ-${creditor}`,
        accountDate: inquiryDate,
        category,
        accountKey,
        status: category === 'soft-inquiry' ? 'Inquiry' : 'Hard Inquiry',
      });
    });
  }

  return items;
};

const normalizePersonalInfoValue = (value: any): string => String(value ?? '').replace(/\s+/g, ' ').trim();

const normalizePersonalInfoValues = (values: any[]): string[] => {
  const uniqueValues = new Map<string, string>();
  values.forEach((value) => {
    const normalizedValue = normalizePersonalInfoValue(value);
    if (!normalizedValue) return;
    const key = normalizedValue.toLowerCase();
    if (!uniqueValues.has(key)) {
      uniqueValues.set(key, normalizedValue);
    }
  });
  return Array.from(uniqueValues.values()).sort((left, right) => left.localeCompare(right));
};

const formatPersonalInfoAddress = (address: any): string => {
  const line1 = address?.StreetAddress || address?.AddressLine1 || address?.Address1 || address?.street || '';
  const line2 = address?.StreetAddress2 || address?.AddressLine2 || address?.Address2 || address?.street2 || '';
  const city = address?.City || address?.city || '';
  const state = address?.State || address?.state || '';
  const zip = address?.Zip || address?.PostalCode || address?.zip || '';
  const street = [line1, line2].filter(Boolean).join(' ').trim();
  const cityStateZip = [city, [state, zip].filter(Boolean).join(' ')].filter(Boolean).join(', ');
  return [street, cityStateZip].filter(Boolean).join(', ').trim();
};

const buildPersonalInfoNegativeItems = (apiSource: any, reportSource: any, detectedLaws: string[] = []): any[] => {
  const root = apiSource?.reportData?.reportData || apiSource?.reportData || apiSource || {};
  const names = Array.isArray(root?.Name)
    ? root.Name
    : Array.isArray(apiSource?.Name)
    ? apiSource.Name
    : [];
  const dobs = Array.isArray(root?.DOB)
    ? root.DOB
    : Array.isArray(apiSource?.DOB)
    ? apiSource.DOB
    : [];
  const addresses = Array.isArray(root?.Address)
    ? root.Address
    : Array.isArray(apiSource?.Address)
    ? apiSource.Address
    : [];
  const employers = Array.isArray(reportSource?.personalInfo?.employers) ? reportSource.personalInfo.employers : [];
  const laws = detectedLaws.length > 0 ? detectedLaws : lawTagsFromLawset(FULL_PERSONAL_INFO_LAWSET);
  const bureauMeta = [
    { bureauId: 3, bureauName: 'Experian' },
    { bureauId: 1, bureauName: 'Equifax' },
    { bureauId: 2, bureauName: 'TransUnion' },
  ];
  const namesForBureau = (bureauId: number) => names.filter((entry: any) => Number(entry?.BureauId ?? entry?.bureauId) === bureauId);
  const primaryNameForBureau = (bureauId: number) => {
    const bureauNames = namesForBureau(bureauId);
    const primary = bureauNames.find((entry: any) => String(entry?.NameType || '').trim().toLowerCase() === 'primary')
      || bureauNames.find((entry: any) => !/(aka|alias|also known as|former)/i.test(String(entry?.NameType || '')))
      || bureauNames[0];
    if (!primary) return [] as string[];
    const parts = [primary?.FirstName || primary?.NameFirst || '', primary?.Middle || primary?.MiddleName || '', primary?.LastName || primary?.NameLast || '', primary?.Suffix || ''].filter(Boolean);
    const fullName = parts.join(' ').trim() || normalizePersonalInfoValue(primary?.Name || primary?.FullName || '');
    return fullName ? [fullName] : [];
  };
  const aliasesForBureau = (bureauId: number) => namesForBureau(bureauId)
    .filter((entry: any) => /(aka|alias|also known as|former)/i.test(String(entry?.NameType || '')))
    .map((entry: any) => [entry?.FirstName || entry?.NameFirst || '', entry?.Middle || entry?.MiddleName || '', entry?.LastName || entry?.NameLast || '', entry?.Suffix || ''].filter(Boolean).join(' ').trim() || normalizePersonalInfoValue(entry?.Name || entry?.FullName || ''));
  const dobForBureau = (bureauId: number) => {
    const value = dobs.find((entry: any) => Number(entry?.BureauId ?? entry?.bureauId) === bureauId)?.DOB;
    return value ? [value] : [];
  };
  const addressesForBureau = (bureauId: number, addressType: 'current' | 'previous') => addresses
    .filter((entry: any) => Number(entry?.BureauId ?? entry?.bureauId) === bureauId)
    .filter((entry: any) => addressType === 'current'
      ? String(entry?.AddressType || entry?.Type || '').trim().toLowerCase() === 'current'
      : String(entry?.AddressType || entry?.Type || '').trim().toLowerCase() !== 'current')
    .map((entry: any) => formatPersonalInfoAddress(entry));
  const employmentForBureau = (bureauId: number) => employers
    .filter((entry: any) => Number(entry?.bureauId ?? entry?.BureauId) === bureauId)
    .map((entry: any) => [entry?.name || entry?.EmployerName || '', entry?.position || entry?.Position || ''].filter(Boolean).join(' - '));

  const fieldConfigs = [
    { key: 'name', label: 'Name', getValues: primaryNameForBureau },
    { key: 'date-of-birth', label: 'Date of Birth', getValues: dobForBureau },
    { key: 'current-address', label: 'Current Address', getValues: (bureauId: number) => addressesForBureau(bureauId, 'current') },
    { key: 'previous-address', label: 'Previous Address', getValues: (bureauId: number) => addressesForBureau(bureauId, 'previous') },
    { key: 'alias', label: 'Alias / AKA', getValues: aliasesForBureau },
    { key: 'employment', label: 'Employment', getValues: employmentForBureau },
  ];

  const itemsByBureau = new Map<string, {
    bureauName: string;
    fieldKeys: string[];
    fieldLabels: string[];
    bureauSummaries: string[];
    comparisonSummaries: string[];
    keyParts: string[];
  }>();
  fieldConfigs.forEach((fieldConfig) => {
    const valuesByBureau = bureauMeta.map(({ bureauId, bureauName }) => ({
      bureauName,
      values: normalizePersonalInfoValues(fieldConfig.getValues(bureauId)),
    }));
    const uniqueSignatures = new Set(valuesByBureau.map(({ values }) => values.map((value) => value.toLowerCase()).join('||')));
    if (uniqueSignatures.size <= 1) return;

    valuesByBureau.forEach(({ bureauName, values }) => {
      const bureauValue = values.length > 0 ? values.join(' | ') : 'Missing';
      const comparisonValue = normalizePersonalInfoValues(
        valuesByBureau
          .filter((entry) => entry.bureauName !== bureauName)
          .flatMap((entry) => entry.values)
      );
      const comparisonSummary = comparisonValue.length > 0 ? comparisonValue.join(' | ') : 'Missing';
      const keyValue = values.length > 0 ? values.join('|').toLowerCase() : 'missing';

      const bureauEntry = itemsByBureau.get(bureauName) || {
        bureauName,
        fieldKeys: [],
        fieldLabels: [],
        bureauSummaries: [],
        comparisonSummaries: [],
        keyParts: [],
      };
      bureauEntry.fieldKeys.push(fieldConfig.key);
      bureauEntry.fieldLabels.push(fieldConfig.label);
      bureauEntry.bureauSummaries.push(`${fieldConfig.label}: ${bureauValue}`);
      bureauEntry.comparisonSummaries.push(`${fieldConfig.label}: ${comparisonSummary}`);
      bureauEntry.keyParts.push(`${fieldConfig.key}:${keyValue}`);
      itemsByBureau.set(bureauName, bureauEntry);
    });
  });

  return Array.from(itemsByBureau.values()).map((bureauEntry) => {
    const normalizedBureau = bureauEntry.bureauName.toLowerCase();
    return {
      id: `personal-information-${normalizedBureau}`,
      key: `personal-information|${normalizedBureau}|${bureauEntry.keyParts.join('||')}`,
      type: 'Personal Information',
      creditor: 'Personal Information',
      bureau: bureauEntry.bureauName,
      accountNumber: '',
      accountDate: '',
      category: 'personal-information',
      accountKey: `personal-information-${normalizedBureau}`,
      status: bureauEntry.bureauSummaries.join(' ; '),
      detectedLaws: laws,
      fieldKey: 'personal-information',
      fieldLabel: bureauEntry.fieldLabels.join(' | '),
      bureauValue: bureauEntry.bureauSummaries.join(' ; '),
      comparisonValue: bureauEntry.comparisonSummaries.join(' ; '),
      mismatchFields: bureauEntry.fieldKeys,
      mismatchLabels: bureauEntry.fieldLabels,
    };
  });
};

