        const data = response.data || response;
        if (!isMounted) return;
        const link = data?.creditRepairLink;
        if (typeof link === 'string' && link.trim()) {
          setAffiliateCreditRepairLink(link.trim());
        } else {
          setAffiliateCreditRepairLink(null);
        }
